<?php $d = $this->view_data; ?>
<section class="page"><div class="container py-3"><h4>Report Harian — <?php echo htmlspecialchars($d['display_name']); ?></h4>
<div class="alert alert-info">Mesin: <strong><?php echo htmlspecialchars($d['machine_name']); ?></strong> · Tanggal operasional: <strong><?php echo htmlspecialchars($d['operational_date']); ?></strong> (06.45 sampai 05.45 esok hari)</div>
<div id="page-report-body" class="table-responsive"><table class="table table-bordered table-sm"><thead><tr><th>Part</th><?php foreach ($d['rows'] as $row) { ?><th><?php echo !empty($row['shift']) ? 'Shift ' . htmlspecialchars($row['shift']) : 'Pemeriksaan'; ?><br><small><?php echo htmlspecialchars($row['user_create']); ?></small><br><a class="btn btn-sm btn-outline-primary mt-1" href="<?php print_link($d['machine_key'] . '/view/' . urlencode($row[$d['id_column']])); ?>">View</a></th><?php } ?></tr></thead><tbody><?php foreach ($d['parts'] as $field => $label) { ?><tr><th><?php echo htmlspecialchars($label); ?></th><?php foreach ($d['rows'] as $row) { $v=$row[$field] ?? ''; ?><td><?php echo $v === 'NOK' ? '<span class="badge badge-danger">NOK</span>' : ($v === 'OK' ? '<span class="badge badge-success">OK</span>' : '-'); ?></td><?php } ?></tr><?php } ?></tbody></table></div>
<a class="btn btn-secondary" href="<?php print_link($d['machine_key']); ?>">Kembali</a></div></section>
